use std::marker::PhantomData;
use std::path::{Path, PathBuf};
#[cfg(feature = "logstream")]
use std::sync::atomic::{AtomicBool, Ordering};
#[cfg(feature = "logstream")]
use std::time::Duration;

use clap::Parser;
use cu29::prelude::*;
#[cfg(feature = "logstream")]
use cu29_logstream::{
    CuStreamRx, CuTwinBuilder, CuTwinLogReader, CuTwinReader, CuTwinStatus, twin::LiveReplay,
};
use cu29_export::{copperlists_reader, structlog_reader};

#[derive(Parser)]
#[command(author, version, about)]
struct EvoVisualizerCli {
    /// The base path for the Copper log family.
    unifiedlog_base: PathBuf,

    /// The interned-string index used to decode structured text logs.
    /// If omitted, structured text logs are skipped.
    #[arg(long)]
    log_index: Option<PathBuf>,
}

pub trait Visualizer<P>
where
    P: CopperListTuple + CuPayloadRawBytes + 'static,
{
    fn visualize_copperlist(&mut self, data: &CopperList<P>) -> CuResult<()>;

    /// Called only when the matching application log index is available.
    fn visualize_text_log(&mut self, _entry: CuLogEntry, _line: String) -> CuResult<()> {
        Ok(())
    }
}

pub struct EvoVisualizer<P, V>
where
    P: CopperListTuple + CuPayloadRawBytes + 'static,
    V: Visualizer<P>,
{
    visualizer: V,
    interned_strings: Option<Vec<String>>,
    p: PhantomData<P>,
}

impl<P, V> EvoVisualizer<P, V>
where
    P: CopperListTuple + CuPayloadRawBytes + 'static,
    V: Visualizer<P>,
{
    pub fn new(visualizer: V) -> Self {
        Self {
            visualizer,
            interned_strings: None,
            p: PhantomData,
        }
    }

    /// Handles a generated `SimStep::CopperListCompleted` callback.
    pub fn copperlist_completed(&mut self, data: &CopperList<P>) -> SimOverride {
        match self.visualizer.visualize_copperlist(data) {
            Ok(()) => SimOverride::ExecutedBySim,
            Err(error) => SimOverride::Errored(error.to_string()),
        }
    }

    /// Loads the string index generated by the same application build as the logs.
    pub fn load_log_index(&mut self, path: impl AsRef<Path>) -> CuResult<()> {
        self.interned_strings = Some(
            cu29_intern_strs::read_interned_strings(path.as_ref()).map_err(|error| {
                CuError::new_with_cause(
                    "Failed to read structured log string index",
                    std::io::Error::other(error),
                )
            })?,
        );
        Ok(())
    }

    pub fn process_log_entry(&mut self, entry: CuLogEntry) -> CuResult<()> {
        let interned_strings = self
            .interned_strings
            .as_deref()
            .ok_or_else(|| CuError::from("A structured log string index has not been loaded"))?;
        let line = rebuild_logline(interned_strings, &entry)?;
        self.visualizer.visualize_text_log(entry, line)
    }

    pub fn run_cli(mut self) -> CuResult<()> {
        let args = EvoVisualizerCli::parse();
        let _ = cu29::logcodec::seed_effective_config_from_log::<P>(&args.unifiedlog_base)?;

        let reader = open_reader(&args.unifiedlog_base, UnifiedLogType::CopperList)?;
        for copperlist in copperlists_reader::<P>(reader) {
            self.visualizer.visualize_copperlist(&copperlist)?;
        }

        if let Some(log_index) = args.log_index {
            self.load_log_index(log_index)?;
            let reader = open_reader(
                &args.unifiedlog_base,
                UnifiedLogType::StructuredLogLine,
            )?;
            for entry in structlog_reader(reader) {
                self.process_log_entry(entry?)?;
            }
        }

        Ok(())
    }

    /// Runs a live twin and forwards its reconstructed data to the visualizer.
    ///
    /// Without `log_index`, CopperLists are still visualized and structured logs
    /// are still archived, but live text-log visualization is skipped. The index
    /// must come from the same application build as the sender.
    #[cfg(feature = "logstream")]
    pub fn run_twin<A, R>(
        mut self,
        builder: CuTwinBuilder<A, R>,
        log_index: Option<&Path>,
        stop: &AtomicBool,
    ) -> CuResult<CuTwinStatus>
    where
        A: LiveReplay<DataSet = P>,
        R: CuStreamRx + 'static,
    {
        if let Some(log_index) = log_index {
            self.load_log_index(log_index)?;
        }

        let (mut twin, mut frames) = builder.spawn()?;
        let mut logs = twin
            .take_log_reader()
            .ok_or_else(|| CuError::from("Copper twin log reader is unavailable"))?;

        while !stop.load(Ordering::Relaxed) {
            frames.wait_timeout(Duration::from_millis(20));
            self.drain_twin::<A>(&mut frames, &mut logs)?;
            if frames.is_closed() {
                break;
            }
        }

        let status = twin.stop()?;
        self.drain_twin::<A>(&mut frames, &mut logs)?;
        Ok(status)
    }

    #[cfg(feature = "logstream")]
    fn drain_twin<A>(
        &mut self,
        frames: &mut CuTwinReader<A>,
        logs: &mut CuTwinLogReader,
    ) -> CuResult<()>
    where
        A: LiveReplay<DataSet = P>,
    {
        while let Some(update) = frames.try_read() {
            self.visualizer
                .visualize_copperlist(&update.frame.copperlist)?;
        }

        while let Some(update) = logs.try_read() {
            if self.interned_strings.is_some() {
                self.process_log_entry(update.frame.entry.clone())?;
            }
        }

        Ok(())
    }
}

fn open_reader(log_base: &Path, log_type: UnifiedLogType) -> CuResult<UnifiedLoggerIOReader> {
    let logger = UnifiedLoggerBuilder::new()
        .file_base_name(log_base)
        .build()
        .map_err(|error| CuError::new_with_cause("Failed to create logger", error))?;
    let UnifiedLogger::Read(logger) = logger else {
        return Err(CuError::from(
            "Expected read-only unified logger in visualizer",
        ));
    };

    Ok(UnifiedLoggerIOReader::new(logger, log_type))
}
